    if not grid or not grid[0]:
        return grid

    m, n = len(grid), len(grid[0])
    original_color = grid[row][col]

    # If the target color is same as original color, no need to do anything
    if original_color == color:
        return grid

    visited = [[False] * n for _ in range(m)]
    border_cells = set()

    def dfs(r: int, c: int):
        if r < 0 or r >= m or c < 0 or c >= n:
            return False

        if (r, c) in visited:
            return True

        if grid[r][c] != original_color:
            return False

        visited[r][c] = True
        is_border = False

